"""Rebuild the supplemental mission, preserving its UUID and external image URLs."""
from pathlib import Path
import html
import json

ROOT = Path(__file__).resolve().parent.parent
IMAGES = json.loads((ROOT/'authoring/images.json').read_text('utf-8'))
STEPS = []
ASSETS = 'https://raw.githubusercontent.com/martin-lift/Edu108/main/missions/ready/8_class/information-technology/phone-call-network/assets/'
CSS = '''body{font:19px/1.65 Arial,"Segoe UI",sans-serif;color:#20354c;background:#fff;margin:0;padding:24px;max-width:960px;box-sizing:border-box}p{margin:16px 0}h3{font-size:24px;color:#126a80;margin:24px 0 10px}strong{color:#145b72}li{margin:9px 0}figure{margin:20px 0;padding:14px;background:#f1f7fa;border:1px solid #dce7ee;border-radius:14px;text-align:center}figure img{display:block;max-width:100%;width:auto;height:auto;max-height:360px;margin:auto;object-fit:contain}figcaption{font-size:13px;line-height:1.5;color:#52687d;margin-top:10px}.gallery{display:flex;flex-wrap:wrap;gap:14px}.gallery figure{flex:1 1 260px;min-width:0;margin:0}.gallery img{max-height:280px}.diagram img{width:100%;max-height:none}.key,.example{padding:16px 20px;border-radius:9px;margin:20px 0}.key{background:#e7f5ef;border-left:5px solid #269378}.example{background:#fff3db;border-left:5px solid #e4ad3b}table{width:100%;border-collapse:collapse;font-size:17px}td,th{border:1px solid #c9dce5;padding:11px;text-align:left;vertical-align:top}th{background:#e6f0f6}a{color:#126797;overflow-wrap:anywhere}@media(max-width:550px){body{padding:14px}td,th{font-size:15px;padding:7px}}'''

def wrap(body):
    return '<!doctype html><html lang="bg"><head><meta charset="utf-8"><style>'+CSS+'</style></head><body>'+body+'</body></html>'

def picture(key):
    im=IMAGES[key]
    credit=''
    if im['license'] not in ('Public domain','CC0'):
        credit=' · '+html.escape(im['author'])+' · <a href="'+html.escape(im['source'],quote=True)+'">източник</a> · <a href="'+html.escape(im['license_url'],quote=True)+'">'+html.escape(im['license'])+'</a>'
    return '<figure><img src="'+html.escape(im['url'],quote=True)+'" alt="'+html.escape(im['caption'],quote=True)+'"><figcaption>'+html.escape(im['caption'])+credit+'</figcaption></figure>'

def gallery(*keys):
    return '<div class="gallery">'+''.join(picture(k) for k in keys)+'</div>'

def diagram(name,caption):
    return '<figure class="diagram"><img src="'+ASSETS+name+'.svg" alt="'+html.escape(caption,quote=True)+'"><figcaption>'+caption+'</figcaption></figure>'

def info(sid,title,body):
    STEPS.append({'id':sid,'step_content':{'type':'information','title':title,'instruction':wrap(body),'instruction_format':'html'},'step_rules':{}})

def choice(sid,question,options,correct,feedback):
    assert len(options)==6 and 1<len(correct)<6
    STEPS.append({'id':sid,'step_content':{'type':'multiple_choice','title':'Провери разбирането си','instruction':wrap('<p>'+question+'</p><p><strong>Избери всички верни отговори.</strong></p>'),'instruction_format':'html','options':[{'id':str(i+1),'text':x} for i,x in enumerate(options)],'correct_option_ids':[str(i+1) for i in correct],'feedback':feedback},'step_rules':{'automatic_feedback':True,'send_progress':True,'ai_feedback':False}})

info('intro','За какво е този урок?',picture('phones')+'''<p>Мая пътува с автобус и се обажда на приятеля си Иван, който е в друг град. Двамата се чуват почти веднага. Между тях обаче има много повече от два телефона: антени, кабели, радиовръзки и компютри на мобилните оператори.</p><p>Ще проследим <strong>пътуването на един телефонен разговор</strong> — от гласа на Мая до високоговорителя на Иван. После ще видим как разговорът може да продължи, докато автобусът се движи, и кога в тази мрежа помагат сателитите.</p><ul><li>Ще разпознаваш <strong>базова станция, клетка и връзка между станции</strong>.</li><li>Ще обясняваш как операторът свързва двата телефона.</li><li>Ще различаваш липса на покритие и претоварена мрежа.</li><li>Ще разбираш кога разговорът минава през <strong>сателит</strong>.</li></ul><div class="key">Всички ситуации и данни са дадени тук. За мисията ти е достатъчен компютър — не е необходимо да имаш телефон.</div>''')

info('voice','Как гласът става информация?',picture('phones')+'''<p>Мая казва: „Пристигам след десет минути.“ Гласът ѝ създава трептения във въздуха. <strong>Микрофонът</strong> на телефона ги превръща в електрически сигнал. Телефонът обработва този сигнал и го представя като цифрови данни — информация, описана с нули и единици.</p><p>За да изпрати данните, телефонът използва <strong>радиосигнал</strong>. Неговата антена обменя сигнали с антената на базова станция в района. През въздуха не лети самият глас като звук; пренася се информацията, от която другият телефон ще възстанови звука.</p><p>При Иван процесът завършва в обратен ред: телефонът получава данните, обработва ги и високоговорителят създава звук. Когато Иван отговори, неговият микрофон започва същото пътуване в обратната посока.</p><div class="example"><strong>Проследи промяната:</strong> глас → микрофон → цифрови данни → радиосигнал. При получателя: данни → обработка → високоговорител → чут глас. По време на разговора обменът продължава и в двете посоки.</div>''')
choice('voice-check','Кои твърдения описват правилно разговора на Мая и Иван?',['Микрофонът преобразува гласа в електрически сигнал.','Телефонът представя гласа като цифрови данни.','Гласът достига до другия град като звук, който се носи през въздуха.','Телефонът обменя радиосигнали с базова станция.','Високоговорителят превръща получения сигнал в чуваем звук.','Само телефонът на човека, който първи се обажда, може да изпраща информация.'],[0,1,3,4],'Микрофонът приема гласа, телефонът обработва информацията и я предава чрез радиосигнал. Получателят възстановява звука с високоговорителя. И двата телефона изпращат и получават информация, когато хората разговарят.')

info('station','Какво има в една базова станция?',gallery('tower','cabinets')+'''<p>До пътя Мая забелязва висока кула с продълговати панели. Това са <strong>антени</strong>, които изпращат и приемат радиосигнали. Те са важна част от базовата станция, но не са цялата станция.</p><p><strong>Базовата станция</strong> е оборудването, чрез което телефоните в определен район се свързват с мобилната мрежа. Освен антени са нужни електронни устройства за обработка на сигналите, електрическо захранване и връзка към останалата мрежа. Част от оборудването може да е близо до антените, а друга — в шкафове или помещения.</p><p>Височината помага сигналът да достига района с по-малко препятствия. Затова антените могат да са върху кула, покрив или друга подходяща конструкция. Самата метална кула е опора; тя не „мисли“ на кого да предаде разговора.</p>'''+picture('roof')+'''<div class="example"><strong>Как да разчиташ снимките:</strong> панелите обслужват телефоните чрез радиовръзка; шкафовете показват част от останалото оборудване. На покрива виждаш как базова станция може да работи и без отделна висока кула.</div>''')
choice('station-check','Кои неща са нужни за работата на базовата станция?',['Антени за обмен на радиосигнали с телефоните.','Електронно оборудване за обработка на сигналите.','Само метална кула, без други устройства.','Електрическо захранване.','Връзка към останалата мобилна мрежа.','Задължително отделна висока кула за всяка станция.'],[0,1,3,4],'Базовата станция се нуждае от антени, електронно оборудване, захранване и връзка към мрежата. Кулата е възможна опора, но антените могат да се монтират и върху покрив.')

info('cells','Защо мрежата се нарича клетъчна?',diagram('cells','Опростена схема: зони на покритие се застъпват; автобусът преминава от една зона към друга.')+'''<p>Една станция не може да осигури добра връзка навсякъде в страната. Затова районът се обслужва от много станции. <strong>Клетка</strong> наричаме зона на радиопокритие, осигурявана от базова станция или от част от нея. Една станция може да обслужва няколко клетки в различни посоки.</p><p>В учебните схеми клетките често са нарисувани като шестоъгълници или кръгове. В действителност няма такива видими граници. Покритието зависи от релефа, сградите, антените и други условия. Зоните могат да се застъпват.</p><p>Когато Мая е в града, около нея има много хора и много телефони. Повече клетки с по-малък обхват позволяват мрежата да обслужва повече потребители. Извън града една клетка може да покрива по-голяма територия.</p><div class="key">Телефонът и мрежата избират подходяща клетка според сигнала и условията. Географски най-близката кула невинаги е тази, която обслужва телефона.</div>''')
choice('cells-check','Кои твърдения за клетките са верни?',['Клетката е зона на радиопокритие.','Границите на реалните клетки са точни шестоъгълници.','Покритието зависи от сгради и релеф.','Една станция може да обслужва клетки в различни посоки.','Зоните на покритие могат да се застъпват.','Телефонът винаги използва географски най-близката кула.'],[0,2,3,4],'Клетката описва радиопокритие, а не оградена територия. Реалните зони се влияят от условията и могат да се застъпват. Станцията може да обслужва няколко посоки; изборът на клетка не се определя само от разстоянието.')

info('transport','Как станциите са свързани помежду си?',gallery('fiber','microwave')+'''<p>Радиосигналът от Мая вече е стигнал до базовата станция. Но Иван е в друг град. За да продължи пътят на разговора, станцията трябва да е свързана с останалата мрежа. Тази част от пътя често се нарича <strong>транспортна връзка</strong>.</p><p>Един начин е <strong>оптичен кабел</strong>. В много тънки влакна информацията се пренася чрез светлинни сигнали. Кабелите свързват съоръженията по земята и могат да пренасят информация за много разговори и други услуги едновременно.</p><p>Друг начин е <strong>насочена микровълнова радиовръзка</strong>. Две антени, насочени една към друга, обменят информация между наземни обекти. Кръглата антена на снимката е пример за такова съоръжение. За добра работа обикновено е нужен свободен път на сигнала между антените.</p><div class="example">Станция край пътя предава информацията по радиовръзка до друг наземен обект, откъдето тя продължава по оптичен кабел. Така един разговор може да използва различни видове връзки по отделните участъци.</div><div class="key">Кръгла антена върху мобилна кула не означава непременно връзка със сателит. Тя може да е насочена към друга наземна станция.</div>''')
choice('transport-check','Кои обяснения за връзките между съоръженията са верни?',['Оптичният кабел пренася информация чрез светлинни сигнали.','Всяка кръгла антена непременно комуникира със сателит.','Насочена радиовръзка може да свързва два наземни обекта.','Един разговор може да премине през радиоучастък и оптичен кабел.','За връзката от базовата станция нататък не е нужно никакво оборудване.','Една транспортна връзка може да пренася информация за много разговори.'],[0,2,3,5],'Станцията се нуждае от връзка към мрежата. Оптичните влакна използват светлинни сигнали, а насочените антени могат да свързват наземни обекти. Пътят може да съчетава различни технологии и да обслужва много разговори.')

info('operator','Как мрежата намира другия телефон?',picture('sim')+'''<p>Мая избира номера на Иван. За мрежата това е указание <strong>кого иска да потърси</strong>. Компютърните системи на оператора управляват свързването. Съвкупността от тези основни системи ще наричаме <strong>ядро на мобилната мрежа</strong>.</p><p>Когато телефонът се включи и се свърже с мрежата, той се регистрира. <strong>SIM картата</strong> съдържа данни, чрез които мрежата разпознава абонамента и проверява правото за достъп. При <strong>eSIM</strong> тази роля се изпълнява от вграден модул с активиран профил.</p><p>Мрежата поддържа информация в кой район е регистриран телефонът на Иван. При входящо обаждане го търси чрез станции в съответния район и организира връзката. Не е необходимо първо да открива GPS координатите му.</p><p>Ако Мая и Иван използват различни оператори, системите на операторите обменят необходимата информация през връзките между своите мрежи. Телефонният номер помага обаждането да бъде насочено към правилния получател.</p><div class="example">В нашата ситуация Иван е включил телефона си и има покритие. Мрежата го открива в обслужвания район; телефонът му звъни и той приема разговора.</div>''')
choice('operator-check','Кои твърдения за свързването с Иван са верни?',['Номерът показва кого Мая иска да потърси.','SIM или eSIM помага да се разпознае абонаментът.','Ядрото на мрежата участва в организирането на връзката.','За всяко обаждане първо задължително се включва GPS на Иван.','Разговор между различни оператори е невъзможен.','Мрежата използва информация за района, в който телефонът е регистриран.'],[0,1,2,5],'Номерът насочва обаждането, SIM/eSIM участва в разпознаването на абонамента, а системите на оператора организират връзката. Регистрацията в мрежата позволява търсене в съответния район; GPS не е задължителна стъпка. Операторите могат да свързват мрежите си.')

info('route','Един разговор от край до край',diagram('route','Пътят на разговора в нашия пример. Двупосочните стрелки показват обмен и в двете посоки.')+'''<p>Нека съберем частите в една история. Мая казва изречението си и телефонът го превръща в данни. По радиовръзка те достигат до обслужващата базова станция. Оттам информацията продължава по транспортната мрежа до системите на оператора.</p><p>Системите насочват разговора към мрежата и станцията, които обслужват Иван. Последният участък до неговия телефон отново е радиовръзка. Телефонът възстановява звука и Иван чува: „Пристигам след десет минути.“</p><p>Когато той отговори „Чакам те на спирката“, информацията пътува в обратната посока. Разговорът е постоянен двупосочен обмен. Схемата показва основните роли; между тях в реалната мрежа може да има още съоръжения.</p><div class="key">Двата телефона не трябва да се „надвикват“ през цялото разстояние между градовете. Всеки използва радиовръзка със станция в своя район, а мрежата свързва тези участъци.</div><div class="example"><strong>В този пример няма сателитен участък.</strong> Голямото разстояние между Мая и Иван само по себе си не означава, че разговорът трябва да мине през Космоса.</div>''')
STEPS.append({'id':'route-answer','step_content':{'type':'open_answer','title':'Разкажи пътуването на разговора','instruction':wrap('''<p>Как изречението на Мая стига до Иван в другия град?</p><p>Обясни със свои думи в 4–6 изречения. Използвай примера „Пристигам след десет минути“ и проследи телефоните, двете базови станции и мрежата на оператора.</p>'''),'instruction_format':'html','reference_answer':'Мая казва „Пристигам след десет минути“ и телефонът ѝ превръща гласа в цифрови данни. Те се предават чрез радиосигнал до базовата станция в нейния район. По транспортните връзки данните стигат до мрежата на оператора, която насочва разговора към станцията, обслужваща Иван. Тази станция изпраща информацията по радиовръзка до неговия телефон. Телефонът възстановява звука и Иван чува изречението. Когато той отговаря, информацията се пренася в обратната посока. За самопроверка: проследи двата телефона, двете станции и свързващата ги мрежа; сателит не е необходим в този пример.'},'step_rules':{'automatic_feedback':True,'send_progress':True,'ai_feedback':False}})

info('handover','Как разговорът продължава в движение?',picture('bus')+'''<p>Автобусът на Мая се отдалечава от първата станция. Сигналът от нейната клетка отслабва, а сигналът от следващата става по-подходящ. Ако връзката остане само с първата клетка, разговорът скоро би се затруднил.</p><p>Телефонът измерва сигналите, а мрежата организира <strong>предаване на връзката към друга клетка</strong>. То е известно и като <strong>handover</strong>. При успешно предаване Мая продължава да говори, без да набира Иван отново и без сама да избира антена.</p><table><tr><th>Момент в учебния пример</th><th>Обслужваща клетка</th><th>Какво чува Мая?</th></tr><tr><td>10:00 — край града</td><td>А</td><td>Разговорът започва.</td></tr><tr><td>10:03 — по пътя</td><td>Б</td><td>Разговорът продължава.</td></tr><tr><td>10:07 — следващото селище</td><td>В</td><td>Разговорът продължава.</td></tr></table><div class="example">Това са готови примерни наблюдения. Между моментите мрежата е предала връзката А → Б → В. Ако по маршрута има участък без достатъчно покритие или предаването не успее, разговорът може да прекъсне.</div>''')
choice('handover-check','Кои изводи следват от пътуването на Мая през клетки А, Б и В?',['Телефонът може да смени обслужващата клетка по време на разговор.','Мая трябва ръчно да избере всяка следваща кула.','Мрежата организира предаването на връзката.','При успешно предаване разговорът може да продължи без ново набиране.','Щом има три клетки по пътя, прекъсване е невъзможно при всякакви условия.','Липсата на достатъчно покритие може да прекъсне разговора.'],[0,2,3,5],'Handover е предаване на връзката към друга клетка. Телефонът и мрежата участват в процеса, без човек да избира кула ръчно. Успешното предаване запазва разговора, но празнина в покритието или неуспешно предаване може да го прекъсне.')

info('problems','Защо понякога връзката се затруднява?',gallery('tunnel','crowd')+'''<p>Снимките показват две различни ситуации. При тунел скалите и конструкцията могат да затруднят достигането на радиосигнала. На пълен стадион сигнал може да има, но много хора искат да използват мрежата едновременно.</p><table><tr><th>Причина</th><th>Какво означава?</th><th>Примерно решение на оператора</th></tr><tr><td><strong>Недостатъчно покритие</strong></td><td>До телефона не достига достатъчно добър радиосигнал.</td><td>Допълнително оборудване в тунел или станция за района.</td></tr><tr><td><strong>Претоварване</strong></td><td>Търсенето надвишава наличния капацитет на мрежата.</td><td>Повече капацитет или допълнителни клетки за събитието.</td></tr><tr><td><strong>Повреда или липса на захранване</strong></td><td>Нужно съоръжение или връзка не работи.</td><td>Ремонт, резервна връзка или резервно захранване.</td></tr></table><p>Планини, дебели стени и разстояние също влияят на покритието. Допълнително оборудване може да осигури връзка и в тунел — затова тунелът не означава автоматично липса на мрежа.</p><div class="key">Силният радиосигнал не гарантира свободен капацитет или изправност на целия път. Затруднена връзка може да има по различни причини.</div>''')
choice('problems-check','Кои обяснения за затруднена връзка са верни?',['Скалите и стените могат да затруднят радиосигнала.','Много едновременни потребители могат да претоварят мрежата.','При силен сигнал целият път на разговора задължително работи без проблем.','Повредена транспортна връзка може да попречи на разговора.','В нито един тунел не може да има мобилна връзка.','Допълнително оборудване може да осигури покритие в тунел.'],[0,1,3,5],'Покритие, капацитет и изправност са различни условия за добра връзка. Препятствията могат да отслабят сигнала, много потребители — да изчерпят капацитета, а повреда — да прекъсне пътя. С подходящо оборудване мобилната мрежа може да работи и в тунели.')

info('satellite-link','Кога сателитът помага на базовата станция?',gallery('satellite','ground')+'''<p>Представи си отдалечено селище на остров. В него има базова станция и захранване, но прокарването на оптичен кабел е трудно, а удобна наземна радиовръзка липсва. Станцията все пак трябва да стига до мрежата на оператора.</p><p>Една възможност е <strong>сателитна транспортна връзка</strong>. Наземен сателитен терминал при станцията обменя сигнали с комуникационен сателит. Сателитът предава информацията до друга наземна станция, свързана с мрежата на оператора. Тази наземна станция служи като вход и изход между сателитната връзка и наземната мрежа.</p>'''+diagram('satellite','Пример: телефон ↔ местна базова станция и сателитен терминал ↔ сателит ↔ наземна станция ↔ мрежа на оператора.')+'''<p>Човекът в селището използва обичайния си телефон за връзка с местната базова станция. Сателитът е в следващ участък от пътя; телефонът не е длъжен да предава директно към него.</p><div class="example"><strong>Сателитът е мост през трудния участък.</strong> Той допълва наземната инфраструктура. В град с добре изградени наземни връзки разговорът обикновено няма нужда от такъв мост.</div>''')
choice('satellite-link-check','Кои твърдения описват сателитната транспортна връзка в островния пример?',['Телефонът първо се свързва с местната базова станция.','Сателитният участък свързва отдалечения обект с останалата мрежа.','Всеки телефон в селището задължително предава директно към сателита.','Наземна станция свързва сателитния участък с наземната мрежа.','Всеки разговор между два града задължително използва сателит.','Сателитът може да помогне, когато удобна наземна транспортна връзка липсва.'],[0,1,3,5],'В този пример телефонът използва базова станция, а сателитът осигурява следващ участък от пътя. Наземната станция свързва този участък с мрежата на оператора. Сателит не е задължителен за всеки разговор или за голямо разстояние.')

info('direct-satellite','Може ли телефон да говори направо със сателит?',gallery('satphone','field')+'''<p>Има и друг начин за сателитна връзка: устройството на човека общува <strong>директно със сателит</strong>. Специализираните сателитни телефони използват такъв подход. На снимките виждаш примери за устройства за сателитна комуникация.</p><p>Развиват се и услуги за пряка връзка между сателити и съвместими мобилни телефони. За тях са нужни подходящо устройство и поддържана услуга в съответния район. Възможностите са различни: една услуга може да предлага съобщения, друга — и разговори или данни. Наличието на смартфон само по себе си не гарантира всички тези услуги.</p><p>За директната сателитна връзка обикновено е важен достатъчно открит изглед към небето. В нашия пример планинар използва сателитен телефон на открито, където няма клетъчно покритие. Неговият сигнал отива към сателит, след това през наземната инфраструктура към другия участник.</p><table><tr><th>Клетъчна връзка</th><th>Пряка сателитна връзка</th></tr><tr><td>Телефонът обменя сигнали с базова станция наблизо.</td><td>Съвместимото устройство обменя сигнали със сателит.</td></tr><tr><td>Нужни са покритие и достъп до мобилната мрежа.</td><td>Нужни са поддържани устройство, услуга и условия за приемане.</td></tr></table><div class="key"><strong>GPS е различна задача.</strong> GPS приемникът приема сигнали от навигационни спътници, за да определи местоположение. Това само по себе си не осигурява телефонен разговор.</div>''')
choice('direct-satellite-check','Кои твърдения за пряката сателитна връзка са верни?',['Сателитен телефон може да обменя сигнали директно със сателит.','Всеки смартфон автоматично предлага сателитни разговори навсякъде.','Възможностите зависят от устройството и услугата.','Откритият изглед към небето може да е важен за връзката.','Щом GPS показва местоположение, телефонният разговор през сателит е гарантиран.','Някои услуги могат да предлагат съобщения, без да предлагат всички други видове комуникация.'],[0,2,3,5],'Пряката връзка използва съвместимо устройство и поддържана сателитна услуга. Условията и наличните функции имат значение. GPS определя местоположение чрез приемане на навигационни сигнали; той не гарантира услуга за телефонен разговор.')

info('summary','Най-важното от урока',diagram('route','Проследи отново пътя на разговора на Мая и Иван.')+'''<ul><li><strong>Гласът става цифрови данни.</strong> Телефоните изпращат и получават информация, от която възстановяват звука.</li><li><strong>Базовите станции осигуряват радиопокритие в клетки.</strong> Антените са част от оборудването им.</li><li><strong>Транспортните връзки и ядрото на мрежата свързват двата края.</strong> Могат да участват оптични кабели, наземни радиовръзки и връзки между оператори.</li><li><strong>При движение мрежата може да предаде разговора към друга клетка.</strong> Лошо покритие, претоварване или повреда могат да затруднят връзката.</li><li><strong>Сателитите допълват мрежата.</strong> Те могат да свързват отдалечени станции или да общуват с подходящи устройства; GPS е за местоположение.</li></ul>''')

mission={'mission_version':4,'mission_id':'3b98570b-604d-41b9-91b0-ff920572d80c','mission_content':{'title':'Как пътува телефонният разговор?','class_name':'8. клас','subject':'Информационни технологии','category':'Допълнителна учебна мисия','lesson':'Как пътува телефонният разговор?','description':'Допълнение към темата за клетъчната мрежа: глас и цифрови данни, базови станции, клетки, транспортни връзки, оператори, движение, покритие и сателити. Всички примери са готови; не е необходим телефон.','content_format':'html','steps':STEPS},'mission_rules':{'allow_back_navigation':True,'show_progress_panel':True}}

